import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import {chromium} from 'playwright-core';
const out=process.env.TRADING_EVIDENCE_DIR;const browser=await chromium.connectOverCDP(process.env.TRADING_CDP_URL);const p=browser.contexts()[0].pages()[0];p.setDefaultTimeout(12000);const errors=[];p.on('pageerror',e=>errors.push(e.message));const evidence={};const settle=()=>p.waitForTimeout(350);const card=p.locator('[data-panel-id="P"]');
async function mode(value){const details=p.locator('details').filter({has:p.getByLabel('Presale fixture',{exact:true})});await details.evaluate(e=>e.open=true);await p.getByLabel('Presale fixture',{exact:true}).selectOption(value);await details.evaluate(e=>e.open=false);await settle();}
async function top(){await p.evaluate(()=>{document.activeElement?.blur();document.querySelectorAll('*').forEach(e=>{if(e.scrollTop)e.scrollTop=0;});});await settle();}
try{
 await p.setViewportSize({width:1414,height:900});await p.goto('http://127.0.0.1:42874/presale');await p.locator('summary').filter({hasText:'Controlled observer'}).waitFor();await mode('open');await card.locator('[data-presale-submit]').waitFor();
 const amount=card.locator('input[inputmode="decimal"]');const element=await amount.elementHandle();const value=await amount.inputValue();
 await card.getByRole('separator',{name:'Resize funding and activity height',exact:true}).press('ArrowDown');assert.ok(await element.evaluate(e=>e.isConnected));assert.equal(await amount.inputValue(),value);
 await p.getByRole('button',{name:'Edit layout',exact:true}).click();await card.getByRole('button',{name:'Move Participation earlier',exact:true}).click();assert.ok(await element.evaluate(e=>e.isConnected));await p.getByRole('button',{name:'Cancel',exact:true}).click();
 for(const state of ['read-pending','error','missing','metadata-incomplete','open','funded','cancelled','trading','delayed']){await mode(state);const text=await card.innerText();evidence[state]=text.slice(-2500);assert.equal(await p.locator('[data-sends]').textContent(),'0');assert.equal(await p.locator('[data-claims]').textContent(),'0');if(state==='read-pending')assert.ok(await card.getByRole('status',{name:'Loading presale',exact:true}).count());if(state==='error')assert.match(text,/Presale could not load/);if(state==='missing')assert.match(text,/Presale information is unavailable/);if(state==='cancelled')await p.screenshot({path:out+'/presale-cancelled.png'});if(state==='funded')await p.screenshot({path:out+'/presale-funded.png'});}
 await mode('open');const cdp=await p.context().newCDPSession(p);evidence.widths=[];
 for(const theme of ['light','dark'])for(const width of [320,407,768,1054,1414]){await p.setViewportSize({width,height:900});await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:width<1024,maxTouchPoints:1});await p.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await settle();assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);const action=card.locator('[data-presale-submit]');await action.scrollIntoViewIfNeeded();assert.ok(await action.evaluate(e=>{const r=e.getBoundingClientRect();return e.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2));}));await top();await p.screenshot({path:out+`/presale-${theme}-${width}.png`});evidence.widths.push({theme,width,actionReachable:true});}
 evidence.runtimeErrors=errors;assert.deepEqual(errors,[]);writeFileSync(out+'/presale-verification.json',JSON.stringify(evidence,null,2));console.log('PASS: presale terminal resize/reorder preserve controller; lifecycle/read states; five widths/light/dark; zero observer sends/claims');
}finally{await browser.close();}
